static public class MPLVerify
{
  static public bool Verify(Google.FlatBuffers.Verifier verifier, uint tablePos)
  {
    return verifier.VerifyTableStart(tablePos)
      && verifier.VerifyString(tablePos, 4 /*ID*/, false)
      && verifier.VerifyField(tablePos, 6 /*CREATED_AT_MS*/, 8 /*long*/, 8, false)
      && verifier.VerifyString(tablePos, 8 /*PLANNER*/, false)
      && verifier.VerifyField(tablePos, 10 /*PROBLEM*/, 1 /*mplProblem*/, 1, false)
      && verifier.VerifyField(tablePos, 12 /*PLAN_EPOCH_MS*/, 8 /*long*/, 8, false)
      && verifier.VerifyString(tablePos, 14 /*OBJECT_ID*/, false)
      && verifier.VerifyString(tablePos, 16 /*TARGET_OBJECT_ID*/, false)
      && verifier.VerifyTable(tablePos, 18 /*REFERENCE_FRAME*/, RFMVerify.Verify, false)
      && verifier.VerifyTable(tablePos, 20 /*REQUEST*/, mplRequestVerify.Verify, false)
      && verifier.VerifyField(tablePos, 22 /*STATUS*/, 1 /*mplStatus*/, 1, false)
      && verifier.VerifyString(tablePos, 24 /*ERROR_CODE*/, false)
      && verifier.VerifyString(tablePos, 26 /*ERROR_MESSAGE*/, false)
      && verifier.VerifyVectorOfTables(tablePos, 28 /*BURNS*/, mplBurnVerify.Verify, false)
      && verifier.VerifyVectorOfTables(tablePos, 30 /*ARCS*/, mplArcVerify.Verify, false)
      && verifier.VerifyField(tablePos, 32 /*TOTAL_DELTA_V_KM_S*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 34 /*TOTAL_TIME_S*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 36 /*TOTAL_DELTA_MASS_KG*/, 8 /*double*/, 8, false)
      && verifier.VerifyTable(tablePos, 38 /*SOLVER*/, mplSolverVerify.Verify, false)
      && verifier.VerifyVectorOfTables(tablePos, 40 /*OPTIONS*/, mplOptionVerify.Verify, false)
      && verifier.VerifyTable(tablePos, 42 /*TRAJECTORY*/, mplTrajectoryVerify.Verify, false)
      && verifier.VerifyTable(tablePos, 44 /*PHASING*/, mplPhasingSolutionVerify.Verify, false)
      && verifier.VerifyTable(tablePos, 46 /*RELATIVE*/, mplRelativeSolutionVerify.Verify, false)
      && verifier.VerifyTable(tablePos, 48 /*RENDEZVOUS*/, mplRendezvousSolutionVerify.Verify, false)
      && verifier.VerifyTable(tablePos, 50 /*GEOMETRY*/, mplGeometrySolutionVerify.Verify, false)
